CREATE TYPE public.app_role AS ENUM ('owner','admin');
CREATE TABLE public.administrators (id uuid PRIMARY KEY DEFAULT gen_random_uuid(), auth_user_id uuid NOT NULL UNIQUE, username text NOT NULL UNIQUE CHECK (username ~ '^[a-z0-9_]{3,32}$'), status text NOT NULL DEFAULT 'active' CHECK (status IN ('active','blocked')), must_change_password boolean NOT NULL DEFAULT true, created_at timestamptz NOT NULL DEFAULT now());
GRANT SELECT ON public.administrators TO authenticated; GRANT ALL ON public.administrators TO service_role;
ALTER TABLE public.administrators ENABLE ROW LEVEL SECURITY;
CREATE TABLE public.user_roles (id uuid PRIMARY KEY DEFAULT gen_random_uuid(), user_id uuid NOT NULL REFERENCES auth.users(id) ON DELETE CASCADE, role public.app_role NOT NULL, UNIQUE(user_id));
GRANT SELECT ON public.user_roles TO authenticated; GRANT ALL ON public.user_roles TO service_role;
ALTER TABLE public.user_roles ENABLE ROW LEVEL SECURITY;
CREATE UNIQUE INDEX one_owner ON public.user_roles(role) WHERE role='owner';
CREATE FUNCTION public.club_member(require_ready boolean DEFAULT true) RETURNS uuid LANGUAGE sql STABLE SECURITY DEFINER SET search_path=public AS $$ SELECT id FROM public.administrators WHERE auth_user_id=auth.uid() AND status='active' AND (NOT require_ready OR NOT must_change_password) $$;
CREATE FUNCTION public.club_owner() RETURNS boolean LANGUAGE sql STABLE SECURITY DEFINER SET search_path=public AS $$ SELECT EXISTS(SELECT 1 FROM public.user_roles r JOIN public.administrators a ON a.auth_user_id=r.user_id WHERE r.user_id=auth.uid() AND r.role='owner' AND a.status='active' AND NOT a.must_change_password) $$;
REVOKE ALL ON FUNCTION public.club_member(boolean), public.club_owner() FROM PUBLIC; GRANT EXECUTE ON FUNCTION public.club_member(boolean), public.club_owner() TO authenticated, service_role;
CREATE POLICY account_read ON public.administrators FOR SELECT TO authenticated USING (auth_user_id=auth.uid() OR public.club_owner());
CREATE POLICY role_read ON public.user_roles FOR SELECT TO authenticated USING (user_id=auth.uid() OR public.club_owner());
CREATE TABLE public.profiles (id uuid PRIMARY KEY DEFAULT gen_random_uuid(), administrator_id uuid NOT NULL UNIQUE REFERENCES public.administrators(id) ON DELETE CASCADE, display_name text NOT NULL, avatar_url text, about text NOT NULL DEFAULT '', rating_philosophy text NOT NULL DEFAULT '', created_at timestamptz NOT NULL DEFAULT now(), updated_at timestamptz NOT NULL DEFAULT now());
GRANT SELECT ON public.profiles TO anon,authenticated; GRANT INSERT,UPDATE,DELETE ON public.profiles TO authenticated; GRANT ALL ON public.profiles TO service_role;
ALTER TABLE public.profiles ENABLE ROW LEVEL SECURITY;
CREATE POLICY profile_read ON public.profiles FOR SELECT TO anon,authenticated USING(true);
CREATE POLICY profile_write ON public.profiles FOR ALL TO authenticated USING(administrator_id=public.club_member() OR public.club_owner()) WITH CHECK(administrator_id=public.club_member() OR public.club_owner());
CREATE FUNCTION public.guard_profile() RETURNS trigger LANGUAGE plpgsql SECURITY DEFINER SET search_path=public AS $$ BEGIN IF EXISTS(SELECT 1 FROM public.user_roles r JOIN public.administrators a ON a.auth_user_id=r.user_id WHERE a.id=NEW.administrator_id AND r.role='owner') THEN RAISE EXCEPTION 'Owner has no public profile'; END IF; IF TG_OP='UPDATE' AND (NEW.id<>OLD.id OR NEW.administrator_id<>OLD.administrator_id) THEN RAISE EXCEPTION 'Profile ownership is immutable'; END IF; NEW.updated_at=now(); RETURN NEW; END $$;
CREATE TRIGGER profile_guard BEFORE INSERT OR UPDATE ON public.profiles FOR EACH ROW EXECUTE FUNCTION public.guard_profile();
CREATE TABLE public.movies (id uuid PRIMARY KEY DEFAULT gen_random_uuid(), tmdb_id integer NOT NULL UNIQUE CHECK(tmdb_id>0), title text NOT NULL, original_title text NOT NULL, overview text NOT NULL DEFAULT '', poster_path text, backdrop_path text, release_date date NOT NULL, runtime integer CHECK(runtime>=0), metadata_updated_at timestamptz NOT NULL DEFAULT now(), created_at timestamptz NOT NULL DEFAULT now());
GRANT SELECT ON public.movies TO anon,authenticated; GRANT ALL ON public.movies TO service_role;
ALTER TABLE public.movies ENABLE ROW LEVEL SECURITY; CREATE POLICY movie_read ON public.movies FOR SELECT TO anon,authenticated USING(true);
CREATE FUNCTION public.guard_release() RETURNS trigger LANGUAGE plpgsql SET search_path=public AS $$ BEGIN IF NEW.release_date>current_date THEN RAISE EXCEPTION 'Unreleased movies are not allowed'; END IF; RETURN NEW; END $$;
CREATE TRIGGER movie_release BEFORE INSERT OR UPDATE ON public.movies FOR EACH ROW EXECUTE FUNCTION public.guard_release();
CREATE TABLE public.reviews (id uuid PRIMARY KEY DEFAULT gen_random_uuid(), movie_id uuid NOT NULL REFERENCES public.movies(id) ON DELETE CASCADE, administrator_id uuid NOT NULL REFERENCES public.administrators(id) ON DELETE CASCADE, rating numeric NOT NULL CHECK(rating BETWEEN 0 AND 10 AND rating=round(rating,1)), recommend boolean NOT NULL, comment text NOT NULL CHECK(char_length(btrim(comment)) BETWEEN 2 AND 1000), created_at timestamptz NOT NULL DEFAULT now(), updated_at timestamptz NOT NULL DEFAULT now(), updated_by uuid NOT NULL REFERENCES public.administrators(id), UNIQUE(movie_id,administrator_id));
GRANT SELECT ON public.reviews TO anon,authenticated; GRANT INSERT,UPDATE,DELETE ON public.reviews TO authenticated; GRANT ALL ON public.reviews TO service_role;
ALTER TABLE public.reviews ENABLE ROW LEVEL SECURITY; CREATE POLICY review_read ON public.reviews FOR SELECT TO anon,authenticated USING(true); CREATE POLICY review_write ON public.reviews FOR ALL TO authenticated USING(administrator_id=public.club_member() OR public.club_owner()) WITH CHECK(administrator_id=public.club_member() OR public.club_owner());
CREATE FUNCTION public.guard_review() RETURNS trigger LANGUAGE plpgsql SET search_path=public AS $$ BEGIN IF TG_OP='UPDATE' AND (NEW.administrator_id<>OLD.administrator_id OR NEW.movie_id<>OLD.movie_id OR NEW.created_at<>OLD.created_at OR NEW.id<>OLD.id) THEN RAISE EXCEPTION 'Review authorship is immutable'; END IF; IF auth.uid() IS NOT NULL THEN NEW.updated_by=public.club_member(); IF NEW.updated_by IS NULL THEN RAISE EXCEPTION 'Active member required'; END IF; END IF; NEW.updated_at=now(); RETURN NEW; END $$;
CREATE TRIGGER review_guard BEFORE INSERT OR UPDATE ON public.reviews FOR EACH ROW EXECUTE FUNCTION public.guard_review();
CREATE TABLE public.watchlist (id uuid PRIMARY KEY DEFAULT gen_random_uuid(), movie_id uuid NOT NULL REFERENCES public.movies(id) ON DELETE CASCADE, administrator_id uuid NOT NULL REFERENCES public.administrators(id) ON DELETE CASCADE, added_at timestamptz NOT NULL DEFAULT now(), UNIQUE(movie_id,administrator_id));
GRANT SELECT ON public.watchlist TO anon,authenticated; GRANT INSERT,DELETE ON public.watchlist TO authenticated; GRANT ALL ON public.watchlist TO service_role;
ALTER TABLE public.watchlist ENABLE ROW LEVEL SECURITY; CREATE POLICY queue_read ON public.watchlist FOR SELECT TO anon,authenticated USING(true); CREATE POLICY queue_write ON public.watchlist FOR ALL TO authenticated USING(administrator_id=public.club_member() OR public.club_owner()) WITH CHECK(administrator_id=public.club_member() OR public.club_owner());
CREATE TABLE public.genres (id uuid PRIMARY KEY DEFAULT gen_random_uuid(), tmdb_genre_id integer NOT NULL UNIQUE, name text NOT NULL);
GRANT SELECT ON public.genres TO anon,authenticated; GRANT ALL ON public.genres TO service_role;
ALTER TABLE public.genres ENABLE ROW LEVEL SECURITY; CREATE POLICY genre_read ON public.genres FOR SELECT TO anon,authenticated USING(true);
CREATE TABLE public.movie_genres (movie_id uuid NOT NULL REFERENCES public.movies(id) ON DELETE CASCADE, genre_id uuid NOT NULL REFERENCES public.genres(id) ON DELETE CASCADE, PRIMARY KEY(movie_id,genre_id));
GRANT SELECT ON public.movie_genres TO anon,authenticated; GRANT ALL ON public.movie_genres TO service_role;
ALTER TABLE public.movie_genres ENABLE ROW LEVEL SECURITY; CREATE POLICY movie_genre_read ON public.movie_genres FOR SELECT TO anon,authenticated USING(true);
CREATE TABLE public.profile_favorite_genres (profile_id uuid NOT NULL REFERENCES public.profiles(id) ON DELETE CASCADE, genre_id uuid NOT NULL REFERENCES public.genres(id) ON DELETE CASCADE, PRIMARY KEY(profile_id,genre_id));
GRANT SELECT ON public.profile_favorite_genres TO anon,authenticated; GRANT INSERT,DELETE ON public.profile_favorite_genres TO authenticated; GRANT ALL ON public.profile_favorite_genres TO service_role;
ALTER TABLE public.profile_favorite_genres ENABLE ROW LEVEL SECURITY; CREATE POLICY favorite_read ON public.profile_favorite_genres FOR SELECT TO anon,authenticated USING(true); CREATE POLICY favorite_write ON public.profile_favorite_genres FOR ALL TO authenticated USING(EXISTS(SELECT 1 FROM public.profiles p WHERE p.id=profile_id AND (p.administrator_id=public.club_member() OR public.club_owner()))) WITH CHECK(EXISTS(SELECT 1 FROM public.profiles p WHERE p.id=profile_id AND (p.administrator_id=public.club_member() OR public.club_owner())));
CREATE FUNCTION public.limit_favorite_genres() RETURNS trigger LANGUAGE plpgsql SECURITY DEFINER SET search_path=public AS $$ BEGIN PERFORM 1 FROM public.profiles WHERE id=NEW.profile_id FOR UPDATE; IF (SELECT count(*) FROM public.profile_favorite_genres WHERE profile_id=NEW.profile_id)>=5 THEN RAISE EXCEPTION 'Maximum five favorite genres'; END IF; RETURN NEW; END $$;
CREATE TRIGGER favorites_limit BEFORE INSERT ON public.profile_favorite_genres FOR EACH ROW EXECUTE FUNCTION public.limit_favorite_genres();
CREATE FUNCTION public.create_member_profile() RETURNS trigger LANGUAGE plpgsql SECURITY DEFINER SET search_path=public AS $$ BEGIN IF NEW.role='admin' THEN INSERT INTO public.profiles(administrator_id,display_name) SELECT id,username FROM public.administrators WHERE auth_user_id=NEW.user_id ON CONFLICT(administrator_id) DO NOTHING; END IF; RETURN NEW; END $$;
CREATE TRIGGER member_profile AFTER INSERT ON public.user_roles FOR EACH ROW EXECUTE FUNCTION public.create_member_profile();
CREATE FUNCTION public.avatar_allowed(path text) RETURNS boolean LANGUAGE sql STABLE SECURITY DEFINER SET search_path=public AS $$ SELECT public.club_owner() OR EXISTS(SELECT 1 FROM public.profiles p WHERE p.id::text=split_part(path,'/',1) AND p.administrator_id=public.club_member()) $$;
REVOKE ALL ON FUNCTION public.avatar_allowed(text) FROM PUBLIC; GRANT EXECUTE ON FUNCTION public.avatar_allowed(text) TO authenticated,service_role;
CREATE POLICY avatar_read ON storage.objects FOR SELECT TO anon,authenticated USING(bucket_id='avatars' AND EXISTS(SELECT 1 FROM public.profiles WHERE id::text=split_part(name,'/',1)));
CREATE POLICY avatar_insert ON storage.objects FOR INSERT TO authenticated WITH CHECK(bucket_id='avatars' AND public.avatar_allowed(name));
CREATE POLICY avatar_update ON storage.objects FOR UPDATE TO authenticated USING(bucket_id='avatars' AND public.avatar_allowed(name)) WITH CHECK(bucket_id='avatars' AND public.avatar_allowed(name));
CREATE POLICY avatar_delete ON storage.objects FOR DELETE TO authenticated USING(bucket_id='avatars' AND public.avatar_allowed(name));
CREATE INDEX reviews_author ON public.reviews(administrator_id); CREATE INDEX reviews_editor ON public.reviews(updated_by); CREATE INDEX watchlist_author ON public.watchlist(administrator_id); CREATE INDEX movie_genres_genre ON public.movie_genres(genre_id); CREATE INDEX favorites_genre ON public.profile_favorite_genres(genre_id);